#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;
using i128 = __int128_t;

static void shift_or(vector<ull>& bits, unsigned long long shift, unsigned long long limit) {
    if (shift == 0 || shift > limit) return;

    size_t wordShift = static_cast<size_t>(shift >> 6);
    unsigned offset = static_cast<unsigned>(shift & 63);
    size_t n = bits.size();

    for (size_t i = n; i-- > wordShift;) {
        ull value = bits[i - wordShift] << offset;
        if (offset && i > wordShift)
            value |= bits[i - wordShift - 1] >> (64 - offset);
        bits[i] |= value;
    }

    unsigned validBits = static_cast<unsigned>((limit & 63) + 1);
    if (validBits < 64)
        bits.back() &= (1ULL << validBits) - 1;
}

static vector<ull> subsetSums(unsigned long long limit,
                              const array<unsigned long long, 8>& counts) {
    vector<ull> bits(static_cast<size_t>((limit >> 6) + 1), 0);
    bits[0] = 1;

    for (unsigned long long i = 0; i < 8; ++i) {
        unsigned long long value = i + 1;
        unsigned long long count = min(counts[i], limit / value);
        unsigned long long block = 1;

        while (count > 0) {
            unsigned long long take = min(block, count);
            shift_or(bits, take * value, limit);
            count -= take;

            if (block <= count)
                block *= 2;
        }
    }
    return bits;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long w;
    cin >> w;

    array<unsigned long long, 8> counts{};
    i128 total = 0;

    for (unsigned long long i = 0; i < 8; ++i) {
        cin >> counts[i];
        total += static_cast<i128>(counts[i]) * (i + 1);
    }

    if (total <= static_cast<i128>(w)) {
        cout << static_cast<unsigned long long>(total) << '\n';
        return 0;
    }

    i128 difference128 = total - static_cast<i128>(w);

    if (difference128 + 7 < static_cast<i128>(w)) {
        unsigned long long difference =
            static_cast<unsigned long long>(difference128);
        unsigned long long limit = difference + 7;
        vector<ull> bits = subsetSums(limit, counts);

        for (unsigned long long removed = difference; removed <= limit; ++removed) {
            if ((bits[removed >> 6] >> (removed & 63)) & 1ULL) {
                cout << static_cast<unsigned long long>(
                            total - static_cast<i128>(removed))
                     << '\n';
                return 0;
            }
        }
    }

    vector<ull> bits = subsetSums(w, counts);

    for (size_t i = bits.size(); i-- > 0;) {
        if (bits[i]) {
            unsigned bit = 63U - static_cast<unsigned>(__builtin_clzll(bits[i]));
            cout << (static_cast<unsigned long long>(i) * 64 + bit) << '\n';
            return 0;
        }
    }

    cout << 0 << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long w;
    cin >> w;

    constexpr long long BLOCK_VALUE = 840;
    vector<pair<int, long long>> items;
    long long bulkBlocks = 0;
    long long maxUsefulBlocks = w / BLOCK_VALUE;

    for (int value = 1; value <= 8; ++value) {
        long long count;
        cin >> count;

        long long blockSize = BLOCK_VALUE / value;
        long long blocks = 0;

        if (count >= blockSize) {
            blocks = count / blockSize - 1;
            count -= blocks * blockSize;
        }

        bulkBlocks = min(maxUsefulBlocks, bulkBlocks + min(blocks, maxUsefulBlocks));
        items.emplace_back(value, count);
    }

    int residualSum = 0;
    for (auto [value, count] : items)
        residualSum += value * static_cast<int>(count);

    vector<char> reachable(residualSum + 1, false);
    reachable[0] = true;

    int currentSum = 0;
    for (auto [value, count] : items) {
        long long group = 1;
        while (count > 0) {
            long long take = min(group, count);
            int weight = static_cast<int>(take * value);

            for (int sum = currentSum; sum >= 0; --sum)
                if (reachable[sum])
                    reachable[sum + weight] = true;

            currentSum += weight;
            count -= take;
            group <<= 1;
        }
    }

    long long answer = 0;
    for (int residual = 0; residual <= residualSum; ++residual) {
        if (!reachable[residual] || residual > w) continue;

        long long blocks = min(bulkBlocks, (w - residual) / BLOCK_VALUE);
        answer = max(answer, residual + blocks * BLOCK_VALUE);
    }

    cout << answer << '\n';
    return 0;
}

